import re

import django.core.validators
from django.db import migrations, models


def preencher_quantidade_treinamento(apps, schema_editor):
    Pendencia = apps.get_model('fichas', 'Pendencia')
    banco = schema_editor.connection.alias
    for pendencia in Pendencia.objects.using(banco).filter(tipo='treinamento').iterator():
        correspondencia = re.search(r'Aprimorar (\d+) perícias', pendencia.descricao)
        if correspondencia:
            quantidade = int(correspondencia.group(1))
            if 1 <= quantidade <= 99:
                Pendencia.objects.using(banco).filter(pk=pendencia.pk).update(quantidade=quantidade)


